(function () {
    'use strict';
    var ua = navigator.userAgent.toLowerCase();
    var isQQ = /qq\//.test(ua);
    var isWeChat = /micromessenger/.test(ua);
    if (!(isQQ || isWeChat)) return;

    var $body = document.body;
    $body.style.padding = 0;
    $body.style.margin = 0;

    /* ---- 1. 音乐播放器自动收起 ---- */
    function collapsePlayer() {
        var p = document.querySelector('xf-music-player');
        if (!p) return false;
        var btn = null;
        try {
            if (p.shadowRoot) btn = p.shadowRoot.querySelector('.switching-btn');
        } catch (e) {}
        if (btn) {
            /* 展开状态时图标带 rotate-180，此时才点击收起 */
            var icon = btn.querySelector('.icon-jiantou2');
            if (icon && /rotate-180/.test(icon.className)) { btn.click(); }
            return true;
        }
        return false;
    }
    /* 播放器初始化有延迟（约 300ms 后才展开），轮询重试至多 10 秒 */
    var tries = 0;
    var collapseTimer = setInterval(function () {
        tries++;
        if (collapsePlayer() || tries > 33) clearInterval(collapseTimer);
    }, 300);

    /* ---- 2. 全屏文字引导层 ---- */
    var overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100vh;z-index:2147483647;'
        + 'background:rgba(0,0,0,.85);display:flex;flex-direction:column;align-items:center;justify-content:center;'
        + 'text-align:center;color:#fff;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;';

    /* 右上角动画箭头：指向浏览器「···」菜单 */
    var arrowStyle = ''
        + '@keyframes ar-point {0%,100%{transform:translate(0,0);opacity:.65}50%{transform:translate(8px,-8px);opacity:1}}'
        + '@keyframes ar-ripple {0%{transform:scale(.6);opacity:.7}100%{transform:scale(1.6);opacity:0}}'
        + '.ar-arrow-wrap{position:absolute;top:10px;right:14px;width:84px;height:84px;pointer-events:none;}'
        + '.ar-arrow-wrap svg{position:absolute;top:14px;right:6px;animation:ar-point 1.4s ease-in-out infinite;}'
        + '.ar-arrow-ring{position:absolute;top:4px;right:22px;width:26px;height:26px;border:3px solid #fff;border-radius:50%;animation:ar-ripple 1.4s ease-out infinite;}';

    var style = document.createElement('style');
    style.textContent = arrowStyle;
    document.head.appendChild(style);

    var arrow = document.createElement('div');
    arrow.className = 'ar-arrow-wrap';
    arrow.innerHTML = '<div class="ar-arrow-ring"></div>'
        + '<svg width="52" height="52" viewBox="0 0 24 24" fill="none">'
        + '<path d="M6 18 L17 7" stroke="#fff" stroke-width="2.6" stroke-linecap="round"/>'
        + '<path d="M9 6.5 H17.5 V15" stroke="#fff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" fill="none"/>'
        + '</svg>';
    overlay.appendChild(arrow);

    var center = document.createElement('div');
    center.innerHTML = ''
        + '<div style="font-size:24px;font-weight:700;letter-spacing:2px;">请在浏览器中打开</div>'
        + '<div style="margin-top:18px;font-size:15px;line-height:2;">点击右上角 "···" 菜单<br>选择 "在浏览器中打开"<br>以获得更好的体验</div>'
        + '<button id="anti-redness-copy" style="margin-top:30px;padding:11px 40px;border:none;border-radius:8px;background:#fff;color:#111;font-size:15px;font-weight:600;cursor:pointer;">复制链接</button>';
    overlay.appendChild(center);

    $body.appendChild(overlay);

    overlay.querySelector('#anti-redness-copy').addEventListener('click', function () {
        var btn = this, url = location.href;
        function done() {
            btn.textContent = '已复制';
            setTimeout(function () { btn.textContent = '复制链接'; }, 1500);
        }
        function fallback() {
            var ta = document.createElement('textarea');
            ta.value = url;
            ta.style.cssText = 'position:fixed;top:-999px;opacity:0;';
            document.body.appendChild(ta);
            ta.focus(); ta.select();
            var ok = false;
            try { ok = document.execCommand('copy'); } catch (e) {}
            document.body.removeChild(ta);
            btn.textContent = ok ? '已复制' : '复制失败';
            setTimeout(function () { btn.textContent = '复制链接'; }, 1500);
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(url).then(done).catch(fallback);
        } else {
            fallback();
        }
    });
})();
